var processor = client.CreateProcessor("orders", "billing-ledger");  // durable subscription
processor.ProcessMessageAsync += async args =>
{
    await HandleAsync(args.Message.Body);              // idempotent
    await args.CompleteMessageAsync(args.Message);     // ack; backlog shrinks
};
await processor.StartProcessingAsync();                // drains the retained backlog

